  const abzan = makeSuggestion({ colorIdentity: ['W', 'B', 'G'] });
  const colorless = makeSuggestion({ colorIdentity: [] });

  const filters = { ...EMPTY_FILTERS, colors: { include: ['R', 'G'], exclude: [] } };
  // Keeping: mono-green, mono-red, gruhl (R,G), colourless
  // Dropping: abzan (W,B,G has W and B, not a subset of {R,G})
  const kept = applyFilters([monoGreen, monoRed, gruhl, abzan, colorless], filters);
  assert.deepStrictEqual(kept, [monoGreen, monoRed, gruhl, colorless]);
});

